create table if not exists hd_kanban.preparacao_eletrica(id uuid primary key default gen_random_uuid(),forno_id uuid not null unique references hd_kanban.fornos(id),status text not null default 'AGUARDANDO_PROGRAMACAO' check(status in('AGUARDANDO_PROGRAMACAO','PREPARACAO_NECESSARIA','MATERIAIS_EM_SEPARACAO','MATERIAIS_PRONTOS','MATERIAIS_INDISPONIVEIS','PREPARACAO_CONCLUIDA')),observacao text,responsavel uuid references auth.users(id),concluido_em timestamptz,updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists hd_kanban.alertas_pcp(id uuid primary key default gen_random_uuid(),forno_id uuid not null references hd_kanban.fornos(id),tipo text not null,motivo text not null,status text not null default 'ABERTO' check(status in('ABERTO','LIDO','RESOLVIDO')),chave_evento text not null unique,created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists hd_kanban.cenarios_simulacao(id uuid primary key default gen_random_uuid(),nome text not null,status text not null default 'RASCUNHO' check(status in('RASCUNHO','PUBLICADO','DESCARTADO')),dados jsonb not null default '{}'::jsonb,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table hd_kanban.preparacao_eletrica enable row level security;alter table hd_kanban.alertas_pcp enable row level security;alter table hd_kanban.cenarios_simulacao enable row level security;
grant select on hd_kanban.preparacao_eletrica,hd_kanban.alertas_pcp,hd_kanban.cenarios_simulacao to authenticated;
create policy leitura_preparacao_eletrica on hd_kanban.preparacao_eletrica for select to authenticated using(true);
create policy leitura_alertas_pcp on hd_kanban.alertas_pcp for select to authenticated using(true);
create policy leitura_cenarios_simulacao on hd_kanban.cenarios_simulacao for select to authenticated using(true);
grant insert,update on hd_kanban.preparacao_eletrica,hd_kanban.alertas_pcp,hd_kanban.cenarios_simulacao to authenticated;
create policy grava_preparacao_eletrica on hd_kanban.preparacao_eletrica for all to authenticated using(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP','ELETRICA')) with check(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP','ELETRICA'));
create policy grava_alertas_pcp on hd_kanban.alertas_pcp for all to authenticated using(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP','ELETRICA')) with check(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP','ELETRICA'));
create policy grava_cenarios on hd_kanban.cenarios_simulacao for all to authenticated using(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP') and created_by=(select auth.uid())) with check(coalesce((select auth.jwt())->'app_metadata'->>'hd_role','CONSULTA') in('ADMIN','PCP') and created_by=(select auth.uid()));
create index if not exists preparacao_eletrica_responsavel_idx on hd_kanban.preparacao_eletrica(responsavel);create index if not exists preparacao_eletrica_updated_by_idx on hd_kanban.preparacao_eletrica(updated_by);create index if not exists alertas_pcp_forno_idx on hd_kanban.alertas_pcp(forno_id);create index if not exists cenarios_created_by_idx on hd_kanban.cenarios_simulacao(created_by);

